def flatten(d, sep="."):
    out = {}
    stack = [("", d)]
    while stack:
        prefix, node = stack.pop()
        for key, value in node.items():
            path = prefix + sep + key if prefix else key
            if isinstance(value, dict):
                stack.append((path, value))
            else:
                out[path] = value
    return out

